/*===========================================================================*\
 * FUNCTION: julian_to_calendar
 *===========================================================================*/
void julian_to_calendar(uint8_t julian_year, uint16_t julian_date, uint8_t *year, uint8_t *month, uint8_t *day)
{
   // If julian year is greater than 99, set it to 25
   if (julian_year > 99)
   {
      julian_year = 25;
   }

   // Convert julian year to calendar year
   *year = julian_year;

   // Convert julian date to calendar date
   int days_in_month[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
   int is_leap_year    = (*year % 4 == 0 && *year % 100 != 0) || *year % 400 == 0;
   if (is_leap_year)
   {
      days_in_month[1] = 29;
   }
   int cumulative_days = 0;
   for (int i = 0; i < 12; i++)
   {
      if (julian_date <= cumulative_days + days_in_month[i])
      {
         *month = i + 1;
         *day   = julian_date - cumulative_days;
         break;
      }
      cumulative_days += days_in_month[i];
   }
}
/*===========================================================================*\
 * FUNCTION: Decimal_To_BCD
 *===========================================================================*/
static uint8 Decimal_To_BCD(uint8 decimal_value)
{
   return (uint8)(((decimal_value / 10u) << 4u) | (decimal_value % 10u));
}

